pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        vm.assume(version > 0 && version <= 100);
        bool reverted;
        try c.atVersion(version) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted, "atVersion should revert because oracle returns zero address");
    }
}

