contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // No precondition needed; the rule is that atVersion should never revert
        // when called with any uint256 argument, because the reference oracle
        // is a contract that always succeeds. The mutant oracle (address(0))
        // causes atVersion to revert due to the non-contract check inside
        // the call to oracle().atVersion().
        try c.atVersion(oracleVersion) {
            // If it returns, the test passes (no revert)
            assertTrue(true);
        } catch {
            // If it reverts, the rule is violated (the buggy version reverts)
            assertTrue(false);
        }
    }
}

