pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Bound the oracle version to a reasonable range
        uint256 boundedVersion = bound(oracleVersion, 0, 1000000);

        // Attempt to call atVersion; catch revert
        bool reverted;
        try c.atVersion(boundedVersion) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: atVersion should succeed ONLY if oracle() returns a contract address (code length > 0)
        bool isContract;
        address oracleAddr = address(c.oracle());
        if (oracleAddr.code.length > 0) {
            isContract = true;
        } else {
            isContract = false;
        }

        assertTrue(reverted != isContract);
    }
}

