        vm.assume(oracleAddr != address(0) && oracleAddr.code.length > 0);

        // We cannot easily set up a full oracle, so we test the property that
        // currentVersion().price should be non-zero if the oracle returns non-zero.
        // Since the bug changes the oracle to address(0), we instead test that
        // when oracle is a contract, the price transformation works correctly.
        // For this we use the fact that the reference always calls oracle().sync()
        // which returns a valid price; the mutant returns zero price when calling
