pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        version = bound(version, 1, 1e6);
        // Call currentVersion() to ensure the oracle is initialized and a version is stored
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("currentVersion()"));
        require(success, "currentVersion() call failed");
        // Now call atVersion(0) – should not revert in reference version
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", version));
        assertTrue(ok, "atVersion should not revert");
        // The returned price should be non-zero (since the mutator returns zero price)
        // OracleVersion is a struct: (uint256 version, uint256 timestamp, int256 price)
        // We decode just the first two fields to check that price is non-zero
        (uint256 ver, uint256 ts, int256 price) = abi.decode(ret, (uint256, uint256, int256));
        assertTrue(price != 0, "Price should be non-zero");
    }
}

