import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        vm.assume(version <= type(uint256).max);
        // The controller() function should never return the zero address
        // after initialization. Since we call atVersion (which internally
        // uses controller()), a zero address would revert due to
        // Address.isContract check. We assert that the call does not revert
        // OR that if it reverts, it's not due to the zero address check
        // (but we can't distinguish revert reasons in a simple fuzz test).
        // To keep the test simple, we just ensure the call succeeds.

        // Drive the contract through a public surface that triggers controller()
        // Note: atVersion will call oracle() then oracle.atVersion(version)
        // If oracle is unset, the call may revert due to Address.isContract
        // when checking oracle address. But the bug is about controller()
        // returning zero address, which affects later calls like collateral().
        // We need to trigger a path that uses controller().
        // A simpler approach: just call controller() directly via the public getter.
        // The contract C inherits from UControllerProvider which defines
        // controller() as a public view function.

        // Direct call to controller() should not return zero address
        address ctrl = address(c.controller());

        // General rule: controller() must never be address(0)
